import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { config } from './config.js';

/**
 * Storage interface:
 *   put(key, buffer, contentType) -> Promise<void>
 *   get(key) -> Promise<Readable>
 *   remove(key) -> Promise<void>
 * Keys are generated by the server (never by the client), e.g. "land/<uuid>/<uuid>.jpg".
 */

const KEY_RE = /^[a-z]+\/[0-9a-f-]{36}\/[0-9a-f-]{36}\.(jpg|png|webp)$/;

function assertKey(key) {
  if (!KEY_RE.test(key)) throw new Error(`Refusing unexpected storage key: ${key}`);
}

function diskStorage() {
  const root = config.uploadDir;
  const resolve = (key) => {
    assertKey(key);
    const full = path.resolve(root, key);
    if (!full.startsWith(root + path.sep)) throw new Error('Path escapes upload directory');
    return full;
  };
  return {
    name: 'local',
    async put(key, buffer) {
      const full = resolve(key);
      await fsp.mkdir(path.dirname(full), { recursive: true });
      await fsp.writeFile(full, buffer, { flag: 'wx' });
    },
    async get(key) {
      const full = resolve(key);
      await fsp.access(full);
      return fs.createReadStream(full);
    },
    async remove(key) {
      await fsp.rm(resolve(key), { force: true });
    },
  };
}

async function s3Storage() {
  const { S3Client, PutObjectCommand, GetObjectCommand, DeleteObjectCommand } = await import('@aws-sdk/client-s3');
  const s3 = new S3Client({
    region: config.s3.region,
    endpoint: config.s3.endpoint,
    forcePathStyle: config.s3.forcePathStyle,
    credentials: { accessKeyId: config.s3.accessKeyId, secretAccessKey: config.s3.secretAccessKey },
  });
  const Bucket = config.s3.bucket;
  return {
    name: 's3',
    async put(key, buffer, contentType) {
      assertKey(key);
      await s3.send(new PutObjectCommand({ Bucket, Key: key, Body: buffer, ContentType: contentType }));
    },
    async get(key) {
      assertKey(key);
      const out = await s3.send(new GetObjectCommand({ Bucket, Key: key }));
      return out.Body;
    },
    async remove(key) {
      assertKey(key);
      await s3.send(new DeleteObjectCommand({ Bucket, Key: key }));
    },
  };
}

export const storage = config.storageDriver === 's3' ? await s3Storage() : diskStorage();

/** Best-effort removal used after a database change has committed. */
export async function removeQuietly(keys) {
  await Promise.all(
    keys.map((k) => storage.remove(k).catch((err) => console.error(`[storage] could not remove ${k}:`, err.message))),
  );
}
